
.status-card {
  width: 100%;
  max-width: 720px;
  margin: 0 auto;
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 8px;
  overflow: hidden;
}

.body {
  display: flex;
}

.overview {
  width: 180px;
  flex-shrink: 0;
  border-right: 1px solid var(--c-border);
  background: var(--c-surface);
}

.content {
  flex: 1;
  min-width: 0;
}

.pane {
  padding: 10px;
  height: 530px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

@media (max-width: 520px) {
  .body {
    flex-direction: column;
  }

  .overview {
    width: 100%;
    border-right: none;
    border-bottom: 1px solid var(--c-border);
  }
}
