
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-height: 100%;
}

.toolbar {
  display: flex;
  justify-content: flex-end;
}

.buttons {
  display: flex;
  gap: 6px;

  button {
    font: inherit;
    font-size: 12px;
    padding: 3px 10px;
    color: var(--c-text-dim);
    background: var(--c-surface-2);
    border: 1px solid var(--c-border);
    border-radius: 5px;
    cursor: pointer;
    transition: color 0.15s, border-color 0.15s;

    &:hover {
      color: var(--c-accent);
      border-color: var(--c-accent);
    }
  }
}

.map-box {
  border: 1px solid var(--c-border);
  border-radius: 6px;
  overflow: hidden;
}

.map {
  display: block;
  width: 100%;
  aspect-ratio: 800 / 640;
  background: var(--c-surface);
  touch-action: none;
  user-select: none;
  cursor: grab;

  &:active {
    cursor: grabbing;
  }
}

.base {
  fill: var(--c-surface);
}

.area {
  fill: var(--c-surface-2);
  stroke: var(--c-border);
  stroke-width: 1.5;
  transition: fill 0.2s, stroke 0.2s;

  &.current {
    fill: rgba(224, 107, 158, 0.16);
    stroke: var(--c-accent);
  }
}

.area-label {
  fill: var(--c-text-dim);
  pointer-events: none;
}

.metro {
  fill: none;
  stroke: var(--c-border);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 6 5;
  pointer-events: none;
}

.road {
  fill: none;
  stroke: var(--c-border);
  stroke-width: 2.5;
  stroke-linecap: round;
  opacity: 0.7;
  pointer-events: none;
}

.road-label {
  fill: var(--c-text-dim);
  opacity: 0.85;
  pointer-events: none;
}

.street-hit {
  fill: none;
  stroke: transparent;
  stroke-width: 14;
  stroke-linecap: round;
  cursor: pointer;
}

.street {
  fill: none;
  stroke: var(--c-accent-2);
  stroke-width: 4;
  stroke-linecap: round;
  opacity: 0.55;
  pointer-events: none;
  transition: opacity 0.15s;

  &.current,
  &.selected {
    opacity: 1;
    stroke: var(--c-accent);
  }
}

.node {
  cursor: pointer;

  .hit {
    fill: transparent;
  }

  .shape {
    fill: var(--c-surface);
    stroke: var(--c-text-dim);
    stroke-width: 1.8;
    transition: stroke 0.15s;
  }

  .inner-dot {
    fill: var(--c-text-dim);
    pointer-events: none;
  }

  &:hover .shape,
  &:hover .inner-dot {
    stroke: var(--c-accent);
    fill: var(--c-accent);
  }

  .node-label {
    fill: var(--c-text-dim);
    pointer-events: none;
    paint-order: stroke;
    stroke: var(--c-surface);
    stroke-width: 3;

    &.current {
      fill: var(--c-accent);
    }
  }

  .current-ring {
    fill: none;
    stroke: var(--c-accent);
    stroke-width: 2;
    animation: pulse 1.6s ease-out infinite;
    pointer-events: none;
  }
}

@keyframes pulse {
  0% {
    stroke-opacity: 0.9;
    r: 9;
  }
  100% {
    stroke-opacity: 0;
    r: 16;
  }
}

.tooltip {
  pointer-events: none;

  rect {
    fill: rgba(23, 23, 31, 0.92);
    stroke: var(--c-border);
  }

  .tip-title {
    fill: var(--c-text);
    font-weight: 600;
  }

  .tip-line {
    fill: var(--c-text-dim);
  }
}

.detail {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;

  .detail-head {
    display: flex;
    align-items: baseline;
    gap: 8px;

    .name {
      color: var(--c-text);
      font-weight: 600;
      font-size: 13px;
    }

    .tag {
      color: var(--c-text-dim);
      font-size: 11px;
    }
  }

  .meta {
    display: flex;
    gap: 14px;
    color: var(--c-accent);
    font-size: 12px;
  }

  .desc {
    color: var(--c-text-dim);
    font-size: 12px;
    line-height: 1.6;
  }
}

.location-text {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 10px;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--c-safe);
  flex-shrink: 0;

  &.moving {
    background: var(--c-accent);
  }
}
